"use client"
import * as React from "react"
import { animate, motion, useMotionTemplate, useMotionValue, useReducedMotion, useSpring, useTransform, type MotionValue } from "framer-motion"
import { ChevronLeft, ChevronRight, Quote } from "lucide-react"
import { cn } from "@/lib/utils"

export interface Testimonial {
  id: string
  quote: string
  name: string
  role: string
  /** Short mark shown in the avatar when there is no image, e.g. initials. */
  initials?: string
  avatarUrl?: string
  /** Company or product name, shown as a wordmark. */
  company?: string
}

export interface TestimonialCoverflowProps {
  items: Testimonial[]
  title?: string
  /** Index shown first. */
  defaultIndex?: number
  onChange?: (index: number) => void
  className?: string
}

const SKY = "#38bdf8"
const GRADIENT = `linear-gradient(125deg,var(--primary),${SKY})`
const ACCENT_TEXT = "text-primary"

function Card({ item, i, pos, w, reduce, active }: { item: Testimonial; i: number; pos: MotionValue<number>; w: number; reduce: boolean; active: boolean }) {
  const d = useTransform(pos, (p) => i - p)
  const x = useTransform(d, (v) => (reduce ? v * (w + 16) : Math.sign(v) * Math.min(Math.abs(v), 1) * w * 0.62 + Math.max(0, Math.abs(v) - 1) * w * 0.3 * Math.sign(v)))
  const rotateY = useTransform(d, (v) => (reduce ? 0 : Math.max(-1.4, Math.min(1.4, v)) * -38))
  const scale = useTransform(d, (v) => (reduce ? 1 : 1 - Math.min(Math.abs(v), 2) * 0.12))
  const z = useTransform(d, (v) => (reduce ? 0 : -Math.min(Math.abs(v), 2) * 120))
  const opacity = useTransform(d, (v) => Math.max(0, 1 - Math.abs(v) * (reduce ? 1 : 0.38)))
  const zi = useTransform(d, (v) => 100 - Math.round(Math.abs(v) * 10))
  // parallax: inner layers slide at different speeds as the card passes
  const px1 = useTransform(d, (v) => (reduce ? 0 : v * -26)), px2 = useTransform(d, (v) => (reduce ? 0 : v * -12)), px3 = useTransform(d, (v) => (reduce ? 0 : v * 18))
  const blur = useTransform(d, (v) => (reduce ? "blur(0px)" : `blur(${Math.min(Math.abs(v), 2) * 1.6}px)`))
  return (
    <motion.li aria-hidden={!active} aria-roledescription="slide" aria-label={`${i + 1}`} className="absolute left-1/2 top-0 list-none" style={{ width: w, marginLeft: -w / 2, x, rotateY, scale, z, opacity, zIndex: zi, filter: blur, transformStyle: "preserve-3d" }}>
      <figure className="relative overflow-hidden rounded-3xl border border-border bg-card p-6 shadow-[0_30px_60px_-30px_color-mix(in_oklab,var(--primary)_60%,transparent)]">
        <motion.div aria-hidden className="absolute -right-10 -top-12 size-44 rounded-full blur-3xl" style={{ x: px3, background: `color-mix(in oklab,${SKY} 35%,transparent)` }} />
        <motion.div style={{ x: px2 }} className="relative"><Quote className={cn("size-8", ACCENT_TEXT)} aria-hidden /></motion.div>
        <motion.blockquote style={{ x: px1 }} className="relative mt-3 text-[17px] leading-relaxed">{item.quote}</motion.blockquote>
        <figcaption className="relative mt-5 flex items-center gap-3">
          <motion.span style={{ x: px3 }} className="grid size-11 shrink-0 place-items-center overflow-hidden rounded-full text-sm font-semibold text-white" >
            {item.avatarUrl ? <img src={item.avatarUrl} alt="" className="size-full object-cover" /> : <span className="grid size-full place-items-center" style={{ background: GRADIENT }}>{item.initials ?? item.name.slice(0, 2)}</span>}
          </motion.span>
          <span className="min-w-0 text-sm"><span className="block font-semibold">{item.name}</span><span className="block text-muted-foreground">{item.role}</span></span>
          {item.company && <span className="ml-auto text-sm font-bold tracking-tight text-muted-foreground">{item.company}</span>}
        </figcaption>
      </figure>
    </motion.li>
  )
}

export function TestimonialCoverflow({ items, title = "What people say", defaultIndex = 0, onChange, className }: TestimonialCoverflowProps) {
  const reduce = !!useReducedMotion()
  const wrap = React.useRef<HTMLDivElement>(null)
  const [w, setW] = React.useState(340)
  const [index, setIndex] = React.useState(defaultIndex)
  const pos = useMotionValue(defaultIndex)
  const [grabbing, setGrabbing] = React.useState(false)
  const down = React.useRef<{ x: number; p: number; t: number; v: number } | null>(null)
  React.useEffect(() => {
    const el = wrap.current; if (!el) return
    const ro = new ResizeObserver(() => setW(Math.min(380, el.offsetWidth - 40))); ro.observe(el); setW(Math.min(380, el.offsetWidth - 40)); return () => ro.disconnect()
  }, [])

  const goTo = React.useCallback((n: number, velocity = 0) => {
    const t = Math.max(0, Math.min(items.length - 1, n))
    setIndex(t); onChange?.(t)
    animate(pos, t, reduce ? { duration: 0.2 } : { type: "spring", stiffness: 140, damping: 17, velocity })
  }, [items.length, onChange, pos, reduce])

  // drag with momentum: the cards follow the finger, release flings to the nearest card
  const onDown = (e: React.PointerEvent) => { if (reduce) return; (e.currentTarget as HTMLElement).setPointerCapture(e.pointerId); pos.stop(); down.current = { x: e.clientX, p: pos.get(), t: performance.now(), v: 0 }; setGrabbing(true) }
  const onMove = (e: React.PointerEvent) => {
    const d = down.current; if (!d) return
    const next = d.p - (e.clientX - d.x) / (w * 0.62)
    const now = performance.now(); d.v = ((d.p - next) - (d.p - pos.get())) / Math.max(1, now - d.t) * 1000; d.t = now
    pos.set(Math.max(-0.4, Math.min(items.length - 0.6, next)))
  }
  const onUp = () => {
    const d = down.current; down.current = null; setGrabbing(false)
    if (!d) return
    const fling = -d.v * 0.12
    goTo(Math.round(pos.get() + fling), -d.v)
  }
  const key = (e: React.KeyboardEvent) => {
    if (e.key === "ArrowRight") { e.preventDefault(); goTo(index + 1) } else if (e.key === "ArrowLeft") { e.preventDefault(); goTo(index - 1) }
    else if (e.key === "Home") { e.preventDefault(); goTo(0) } else if (e.key === "End") { e.preventDefault(); goTo(items.length - 1) }
  }

  const mx = useSpring(useMotionValue(0), { stiffness: 80, damping: 20 })
  const progress = useTransform(pos, [0, Math.max(1, items.length - 1)], ["0%", "100%"])
  const glow = useMotionTemplate`radial-gradient(60% 60% at ${useTransform(pos, [0, Math.max(1, items.length - 1)], ["20%", "80%"])} 40%, color-mix(in oklab, var(--primary) 28%, transparent), transparent)`
  void mx

  return (
    <section aria-roledescription="carousel" aria-label={title} className={cn("relative w-full max-w-xl overflow-hidden rounded-3xl border border-border bg-background p-5 pb-6 text-foreground", className)}>
      <motion.div aria-hidden className="pointer-events-none absolute inset-0" style={{ background: glow }} />
      <div className="relative flex items-center justify-between">
        <h2 className="text-lg font-semibold tracking-tight">{title}</h2>
        <div className="flex gap-1.5">
          {[-1, 1].map((n) => (
            <motion.button key={n} type="button" onClick={() => goTo(index + n)} disabled={index + n < 0 || index + n > items.length - 1} aria-label={n < 0 ? "Previous testimonial" : "Next testimonial"}
              whileTap={reduce ? undefined : { scale: 0.85 }} whileHover={reduce ? undefined : { scale: 1.08 }}
              className="grid size-11 place-items-center rounded-full border border-border bg-card outline-none hover:bg-muted focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring disabled:opacity-35">
              {n < 0 ? <ChevronLeft className="size-4" aria-hidden /> : <ChevronRight className="size-4" aria-hidden />}
            </motion.button>
          ))}
        </div>
      </div>

      <div ref={wrap} tabIndex={0} role="group" aria-label="Use the left and right arrow keys, or drag" onKeyDown={key} onPointerDown={onDown} onPointerMove={onMove} onPointerUp={onUp} onPointerCancel={onUp}
        className={cn("relative mt-4 h-[17.5rem] touch-pan-y select-none rounded-2xl outline-none focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring", grabbing ? "cursor-grabbing" : "cursor-grab")} style={{ perspective: 1000 }}>
        <ul className="relative h-full" style={{ transformStyle: "preserve-3d" }} aria-live="polite">
          {items.map((it, i) => <Card key={it.id} item={it} i={i} pos={pos} w={w} reduce={reduce} active={i === index} />)}
        </ul>
      </div>

      <div className="relative mt-3 flex items-center gap-4">
        <div className="h-1 flex-1 overflow-hidden rounded-full bg-muted"><motion.div className="h-full rounded-full" style={{ width: progress, background: GRADIENT }} /></div>
        <div className="flex">
          {items.map((it, i) => (
            <button key={it.id} type="button" aria-label={`Show testimonial ${i + 1} of ${items.length}`} aria-current={i === index} onClick={() => goTo(i)}
              className="grid size-6 min-h-6 place-items-center outline-none focus-visible:outline-2 focus-visible:outline-ring sm:size-7">
              <motion.span className="block rounded-full" animate={{ width: i === index ? 18 : 6, background: i === index ? "var(--primary)" : "var(--border)" }} style={{ height: 6 }} transition={{ type: "spring", stiffness: 400, damping: 22 }} />
            </button>
          ))}
        </div>
      </div>
    </section>
  )
}

const DEMO: Testimonial[] = [
  { id: "1", quote: "We replaced three tools with one and nobody missed the old ones. Setup took an afternoon, and the team was productive the next morning.", name: "Maya Linden", role: "Head of Operations", company: "Northwind" },
  { id: "2", quote: "The part I like most is how little it asks of me. It works, it stays out of the way, and the support replies are written by people.", name: "Tomás Reyes", role: "Founder", company: "Lumen & Co" },
  { id: "3", quote: "Our designers finally have one place for feedback. Review rounds that took a week now finish in a day.", name: "Ingrid Solberg", role: "Design Lead", company: "Parallel" },
  { id: "4", quote: "Clear pricing, fast pages, no surprises. I would recommend it to anyone who is tired of fighting their software.", name: "Dev Patel", role: "Engineering Manager", company: "Brightside" },
  { id: "5", quote: "I tried it for a weekend project and ended up moving the whole company over by Friday.", name: "Chloe Martin", role: "CTO", company: "Fieldnote" },
]

export default function Demo() {
  return (
    <div data-theme="cobalt" className="fixed inset-0 grid place-items-center overflow-auto bg-background p-6 text-foreground">
      <TestimonialCoverflow items={DEMO} defaultIndex={1} />
    </div>
  )
}

